//! User commands: users, login and registration.
//!
//! Passwords are hashed by the handler; a command only sees the hash. Tokens
//! are generated by the handler too, so sending the mail stays outside.
//! Hashing, mails and the JWT cookie are the server's business.

use uuid::Uuid;

use crate::{actor::Actor, error::CommandError, ids::UserId, roles::Role};

/// What a login checks.
#[derive(Debug, Clone)]
pub struct Credentials {
    pub id: UserId,
    /// The stored password hash.
    pub password_hash: String,
}

/// A user found by email, e.g. to mail them a link.
#[derive(Debug, Clone)]
pub struct UserContact {
    pub id: UserId,
    pub name: String,
}

/// Creates a user with an unverified email together with the token that
/// verifies it, in one transaction.
#[derive(Debug, Clone)]
pub struct Register {
    pub name: String,
    pub email: String,
    pub password_hash: String,
    /// The token the verification mail carries.
    pub email_token: Uuid,
}

/// The login data of the user with this email.
#[derive(Debug, Clone)]
pub struct Login {
    pub email: String,
}

/// Marks the email behind the token as verified and drops the user's tokens.
#[derive(Debug, Clone)]
pub struct VerifyEmail {
    pub token: Uuid,
}

/// Replaces the open password reset tokens of the user with this email.
#[derive(Debug, Clone)]
pub struct RequestPasswordReset {
    pub email: String,
    /// The token the reset mail carries.
    pub token: Uuid,
}

/// Sets a new password hash for the user the token belongs to and drops that
/// user's reset tokens.
#[derive(Debug, Clone)]
pub struct ResetPassword {
    pub token: Uuid,
    pub password_hash: String,
}

/// Replaces the open verification tokens of the acting user.
#[derive(Debug, Clone)]
pub struct ResendMailValidation {
    /// The token the new verification mail carries.
    pub token: Uuid,
}

/// Makes `roles` exactly the roles of the user.
#[derive(Debug, Clone)]
pub struct SetUserRoles {
    pub user_id: UserId,
    pub roles: Vec<Role>,
}

impl SetUserRoles {
    /// Admins can't drop their own Admin role, so there's always one left.
    ///
    /// # Errors
    /// `Forbidden` if the actor would take the role from themselves.
    pub fn check(&self, actor: &Actor) -> Result<(), CommandError> {
        if actor.user_id == self.user_id && !self.roles.contains(&Role::Admin) {
            return Err(CommandError::Forbidden);
        }
        Ok(())
    }
}

/// The write side of the user area of the API; one method per endpoint.
///
/// The anonymous endpoints (`register`, `login`, `verify_email`,
/// `request_password_reset`, `reset_password`) take no actor.
#[async_trait::async_trait]
pub trait UserCommands: Send + Sync {
    /// The new user's id. `Rejected` if the email is registered already.
    async fn register(&self, cmd: Register) -> Result<UserId, CommandError>;

    /// `NotFound` for an unknown email.
    async fn login(&self, cmd: Login) -> Result<Credentials, CommandError>;

    /// The user the token verified; `NotFound` for an unknown token.
    async fn verify_email(&self, cmd: VerifyEmail) -> Result<UserId, CommandError>;

    /// The user to mail; `NotFound` for an unknown email.
    async fn request_password_reset(
        &self,
        cmd: RequestPasswordReset,
    ) -> Result<UserContact, CommandError>;

    /// `NotFound` for an unknown token.
    async fn reset_password(&self, cmd: ResetPassword) -> Result<(), CommandError>;

    async fn resend_mail_validation(
        &self,
        actor: &Actor,
        cmd: ResendMailValidation,
    ) -> Result<(), CommandError>;

    /// `Forbidden` if the actor drops their own Admin role (see
    /// [`SetUserRoles::check`]), `NotFound` for an unknown user.
    async fn set_user_roles(&self, actor: &Actor, cmd: SetUserRoles) -> Result<(), CommandError>;
}
